#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Roteiro dos passos que só o autor pode fazer nesta máquina (ticket 06):
# provedor do modelo e credencial no .env, e Docker Desktop.
# Uso, a partir da raiz do repositório:  bash scripts/configurar_maquina.sh

# Caminhos de instalação padrão no Windows: um terminal aberto antes da
# instalação ainda não os tem no PATH.
_achar() {  # _achar nome caminho-windows-padrão
  if command -v "$1" >/dev/null 2>&1; then command -v "$1"; return 0; fi
  [[ -x "$2" ]] && { printf '%s' "$2"; return 0; }
  return 1
}

run_wizard() {

TOTAL_STAGES=6
cd "$(dirname "$0")/.."

banner "rag-relatorio-sus: chave do modelo, créditos do Google AI Pro e Docker Desktop"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Escolher o provedor do modelo"
if [[ ! -f "$ENV_FILE" ]]; then
  (umask 077 && cp .env.exemplo "$ENV_FILE")
  say "Criei o .env a partir do .env.exemplo (o .env fica fora do git)."
fi
say "gemini: API do Google (Google AI Studio). É ela que gera os números publicados."
say "        Roda no plano gratuito ou com os créditos mensais do seu Google AI Pro (etapa 3)."
say "ollama: modelo local, sem custo. Serve para usar o assistente, não para publicar números."
PROVEDOR=""
while [[ "$PROVEDOR" != "gemini" && "$PROVEDOR" != "ollama" ]]; do
  ask PROVEDOR "Provedor (gemini ou ollama):"
done
write_env PROVEDOR "$PROVEDOR"
pause "Enter para continuar"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Gemini: chave da API"
if [[ "$PROVEDOR" != "gemini" ]]; then
  note "Pulado: o provedor escolhido é ollama."
  pause "Enter para continuar"
else
  say "Use a MESMA conta Google do seu Google AI Pro: é nela que os créditos da etapa 3 caem."
  say "Criar a chave não cobra nada e não pede cartão."
  open_url "https://aistudio.google.com/apikey"
  step "Entre com a conta Google do AI Pro e aceite os termos do AI Studio, se for pedido."
  step "Clique em Create API key (Criar chave de API) e escolha ou crie um projeto."
  step "Copie a chave (começa com AIza)."
  GEMINI_API_KEY=""
  while [[ -z "$GEMINI_API_KEY" ]]; do
    ask_secret GEMINI_API_KEY "Cole a chave (não aparece na tela):"
  done
  write_env GEMINI_API_KEY "$GEMINI_API_KEY"
  say "Conferindo a chave com a lista de modelos (não gasta cota)..."
  if GEMINI_API_KEY="$GEMINI_API_KEY" uv run --no-sync python scripts/conferir_chave.py >/dev/null 2>&1; then
    printf '  %s✓ chave válida, e os modelos dos parâmetros estão disponíveis%s\n' "$GREEN" "$RESET"
  else
    warn "A chave não passou na conferência (chave errada ou sem acesso aos modelos dos parâmetros)."
    SKIPPED+=("conferir a chave do Gemini: rode o wizard de novo e cole outra chave")
  fi
  pause "Enter para continuar"
fi

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Google AI Pro: créditos do Google Cloud para a API (opcional)"
if [[ "$PROVEDOR" != "gemini" ]]; then
  note "Pulado: o provedor escolhido é ollama."
  pause "Enter para continuar"
else
  say "O que o Google AI Pro dá, e o que não dá, para este projeto:"
  note "  • Os limites maiores do AI Pro valem só dentro do site do AI Studio (Playground e Build)."
  note "    A chave de API, que é o que o projeto usa, não ganha limite maior por causa do AI Pro."
  note "  • Para a API, o AI Pro dá créditos mensais do Google Cloud, pelo Google Developer Program."
  note "    Para usá-los, o projeto do AI Studio precisa de faturamento, e o Google pede um"
  note "    pré-pagamento mínimo de US\$ 5. Os créditos são gastos antes desse saldo."
  note "  • Com pré-pago e recarga automática desligada, o máximo que sai do seu bolso é o que você"
  note "    pré-pagou. Quando o saldo zera, a API para (erro 402) e a avaliação para junto."
  note "  • Com faturamento, o projeto sai do plano gratuito e passa ao Tier 1, com cota maior (veja no"
  note "    AI Studio), e o Google deixa de usar os seus prompts para melhorar os produtos dele."
  say "Sem esta etapa, tudo roda no plano gratuito, de graça, só que mais devagar (a cota diária é menor)."
  if confirm "Usar os créditos do Google AI Pro (exige pré-pagar no mínimo US\$ 5)?"; then
    say "Parte 1: vincular o AI Pro ao Google Developer Program."
    open_url "https://developers.google.com/program"
    step "Entre com a MESMA conta Google do AI Pro e clique em Join the program (Participar do programa)."
    step "No seu perfil do programa, vincule o plano Google AI Pro (Link your Google AI Pro plan)."
    step "Siga o pedido para resgatar os créditos mensais do Google Cloud, se aparecer."
    pause "Enter quando o AI Pro estiver vinculado"
    say "Parte 2: ligar o faturamento pré-pago no projeto da chave."
    open_url "https://aistudio.google.com/apikey"
    step "Na linha do projeto da sua chave, clique em Set up billing (Configurar faturamento)."
    step "Crie ou escolha uma conta de faturamento, na mesma conta Google."
    step "Escolha Prepay (pré-pago), NÃO Postpay (pós-pago), e adicione o mínimo de US\$ 5."
    step "Deixe a recarga automática (auto-reload) DESLIGADA."
    step "Na página Spend do projeto, em Monthly spend cap → Edit spend cap, defina um teto mensal baixo."
    step "Confira na conta de faturamento se os créditos do Developer Program aparecem."
    if confirm "Ficou em Prepay, com a recarga automática desligada?"; then
      write_env GEMINI_PLANO "creditos-ai-pro"
      printf '  %s✓ projeto pago com os créditos do AI Pro; teto de gasto = o saldo pré-pago%s\n' "$GREEN" "$RESET"
    else
      warn "Sem Prepay e sem a recarga desligada, o gasto não tem teto. Deixei o plano como gratuito."
      write_env GEMINI_PLANO "gratuito"
      SKIPPED+=("faturamento do Gemini: trocar para Prepay sem recarga automática e rodar o wizard de novo")
    fi
  else
    write_env GEMINI_PLANO "gratuito"
    note "Fica no plano gratuito. Para mudar depois, rode o wizard de novo."
  fi
  pause "Enter para continuar"
fi

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Ollama: instalar e baixar o modelo"
if [[ "$PROVEDOR" != "ollama" ]]; then
  note "Pulado: o provedor escolhido é gemini."
  pause "Enter para continuar"
else
  OLLAMA_BIN=$(_achar ollama "${LOCALAPPDATA:-}/Programs/Ollama/ollama.exe" || true)
  if [[ -z "$OLLAMA_BIN" ]]; then
    say "Vou instalar o Ollama pelo winget. O Windows pode pedir permissão de administrador."
    if confirm "Instalar o Ollama agora?"; then
      winget.exe install --id Ollama.Ollama -e --accept-source-agreements --accept-package-agreements || true
      OLLAMA_BIN=$(_achar ollama "${LOCALAPPDATA:-}/Programs/Ollama/ollama.exe" || true)
    fi
  fi
  if [[ -z "$OLLAMA_BIN" ]]; then
    warn "Ollama não encontrado. Instale por https://ollama.com/download e rode o wizard de novo."
    SKIPPED+=("instalar o Ollama")
  else
    note "Padrão: qwen2.5:7b (cabe nos 8 GB da RTX 5060 Ti). Pode digitar outro."
    OLLAMA_MODELO=""
    ask OLLAMA_MODELO "Modelo do Ollama (Enter = qwen2.5:7b):" || true
    [[ -z "$OLLAMA_MODELO" ]] && OLLAMA_MODELO="qwen2.5:7b"
    say "Baixando $OLLAMA_MODELO (alguns GB; pode demorar)..."
    if "$OLLAMA_BIN" pull "$OLLAMA_MODELO"; then
      write_env OLLAMA_MODELO "$OLLAMA_MODELO"
      write_env OLLAMA_URL "http://localhost:11434"
    else
      warn "O download falhou. Abra o aplicativo Ollama (ele sobe o servidor) e rode o wizard de novo."
      SKIPPED+=("baixar o modelo $OLLAMA_MODELO no Ollama")
    fi
  fi
  pause "Enter para continuar"
fi

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Docker Desktop"
DOCKER_BIN=$(_achar docker "/c/Program Files/Docker/Docker/resources/bin/docker.exe" || true)
if [[ -z "$DOCKER_BIN" ]]; then
  say "O Docker Desktop roda sobre o WSL 2. O winget instala o programa; o Windows pode pedir"
  say "permissão de administrador e uma reinicialização."
  if confirm "Instalar o Docker Desktop agora?"; then
    winget.exe install --id Docker.DockerDesktop -e --accept-source-agreements --accept-package-agreements || true
    DOCKER_BIN=$(_achar docker "/c/Program Files/Docker/Docker/resources/bin/docker.exe" || true)
  fi
fi
if [[ -z "$DOCKER_BIN" ]]; then
  warn "Docker não encontrado. Instale por https://docs.docker.com/desktop/setup/install/windows-install/"
  SKIPPED+=("instalar o Docker Desktop e rodar o wizard de novo")
else
  step "Se o instalador pediu, reinicie o Windows e rode este wizard de novo (ele lembra o que já foi feito)."
  step "Abra o Docker Desktop pelo menu Iniciar e aceite os termos de uso."
  step "Se ele avisar que falta o WSL, rode no PowerShell: wsl --install, reinicie e volte."
  step "Espere o indicador do motor (canto inferior esquerdo) ficar verde: Engine running."
  pause "Enter quando o Docker Desktop estiver rodando"
  if "$DOCKER_BIN" version >/dev/null 2>&1 && "$DOCKER_BIN" compose version >/dev/null 2>&1; then
    printf '  %s✓ docker e docker compose respondendo%s\n' "$GREEN" "$RESET"
  else
    warn "O docker não respondeu. O Docker Desktop está aberto e com o motor rodando?"
    SKIPPED+=("abrir o Docker Desktop e conferir com: docker version")
    DOCKER_BIN=""
  fi
fi
pause "Enter para continuar"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Teste final: a API no contêiner (opcional)"
if [[ -z "$DOCKER_BIN" ]]; then
  note "Pulado: o Docker não está pronto."
elif confirm "Subir a API agora? Na primeira vez leva uns 10 minutos (baixa o modelo de embeddings e constrói o índice)."; then
  "$DOCKER_BIN" compose up --build -d
  say "Esperando a API responder em http://localhost:8000/saude (até 30 minutos)..."
  pronto=""
  for _ in $(seq 1 180); do
    if curl -fs http://localhost:8000/saude >/dev/null 2>&1; then pronto=1; break; fi
    sleep 10
  done
  if [[ -n "$pronto" ]]; then
    printf '  %s✓ API no ar%s\n' "$GREEN" "$RESET"
    open_url "http://localhost:8000/docs"
    step "Em POST /perguntar, clique em Try it out, faça uma pergunta e confira resposta, páginas e Trechos."
    note "Para desligar depois: docker compose down (o modelo e o índice ficam nos volumes)."
  else
    warn "A API não respondeu a tempo. Veja o que aconteceu com: docker compose logs api"
    SKIPPED+=("conferir a API no contêiner: docker compose logs api")
  fi
else
  SKIPPED+=("testar a API no contêiner: docker compose up --build, e abrir http://localhost:8000/docs")
fi
pause "Enter para terminar"

finish
}

run_wizard "$@"; exit
